SELECT CASE WHEN rating >= 3.4 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END rating_bucket, city, SUM(CASE WHEN city = 'Singapore' THEN rating ELSE 0 END) singapore_rating, AVG(rating) avg_rating, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) city_values FROM suppliers GROUP BY CASE WHEN rating >= 3.4 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END, city HAVING singapore_rating < 32;
